-- ============================================================
-- seed-chuokai-zg-dokusya-v3-plus30.sql
--   Additive: 30 new 購読者 (t_dokusya) + 1 履歴 (t_dokusya_rireki)
--   each, for the JA owned by CHUOKAI account 'chuokai_zg'.
--   PORTABLE: ja_id is resolved FROM the account at load time; every
--   FK (kanri_shiten / shiten / hanbaiten / tanka) is resolved by its
--   business code under that ja_id; PKs come from the sequences — so
--   this runs on any DB where 'chuokai_zg' exists, whatever ja_id it
--   has (dev: 144, some exports: 108).
--   kumiaiin_code = 'V3-001'..'V3-030'.
--   IDEMPOTENT: re-run deletes prior V3-% rows for this ja first.
--   Generated: 2026-07-10
--   Load: psql -U <user> -d <db> -v ON_ERROR_STOP=1 -f seed-chuokai-zg-dokusya-v3-plus30.sql
-- ============================================================

\set ON_ERROR_STOP on

-- Resolve the target ja_id from the chuokai account (fail loudly if absent).
SELECT ja_id AS jaid FROM m_account WHERE login_id = 'chuokai_zg' AND deleted_at IS NULL \gset
\if :{?jaid}
\else
  \echo '!! account chuokai_zg not found — nothing to seed'
  \quit
\endif
\echo 'Seeding 30 dokusya for chuokai_zg, ja_id=' :jaid

BEGIN;

-- Idempotent cleanup of previous V3 load (child first).
DELETE FROM t_dokusya_rireki WHERE ja_id = :jaid AND kumiaiin_code LIKE 'V3-%';
DELETE FROM t_dokusya        WHERE ja_id = :jaid AND kumiaiin_code LIKE 'V3-%';

