  henko_riyu, saishin_data_flg, zougen_hokoku_flg, shinki_flg, kaiyaku_flg,
  zenkai_hanbaiten_id, zenkai_dokusya_busu, zenkai_yubin_no, zenkai_todofuken_code,
  zenkai_shikuchoson, zenkai_chome_banchi, zenkai_tatemono_mei, hanbaiten_tekiyo_date, torikeshi_flg
)
SELECT
  dokusya_id, rireki_no, ja_id, kanri_shiten_id, shiten_id, kumiaiin_code, dokusya_shubetsu, tetsuzuki_shurui, denshi_dokusya_shubetsu, shimei_sei, shimei_mei, shimei_kana_sei, shimei_kana_mei, dokusya_busu, yubin_no, todofuken_code, shikuchoson, chome_banchi, tatemono_mei, renrakusaki_1, renrakusaki_2, email, mail_magazine_flg, birth_year, gender, haitatsu_same_flg, haitatsu_yubin_no, haitatsu_todofuken_code, haitatsu_shikuchoson, haitatsu_chome_banchi, haitatsu_tatemono_mei, haitatsu_renrakusaki_1, haitatsu_renrakusaki_2, haitatsu_shimei_sei, haitatsu_shimei_mei, haitatsu_shimei_kana_sei, haitatsu_shimei_kana_mei, hanbaiten_id, tanka_id, yubin_kubun, shiharai_hoho, dokusyaryo_shiharai_cycle, bank_branch_code, bank_branch_name, hikiotoshi_yokin_shubetsu, hikiotoshi_koza_no, hikiotoshi_koza_meigi, dokusyaso_bunrui, nogyosya_bunrui, shoki_dokusya_kaishi_date, dokusya_kaishi_date, dokusya_chushi_date, joho_henko_tekiyo_date, seikyu_kaishi_month, biko, denshi_shonin_status, created_at, created_by,
  '', true, true, true, false,
  NULL, NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, false
FROM t_dokusya
WHERE ja_id = :jaid AND kumiaiin_code LIKE 'V3-%';

-- advance identity sequences past the loaded max (safe: counter only).
SELECT setval(pg_get_serial_sequence('t_dokusya', 'dokusya_id'), (SELECT COALESCE(MAX(dokusya_id), 1) FROM t_dokusya));
SELECT setval(pg_get_serial_sequence('t_dokusya_rireki', 'dokusya_rireki_id'), (SELECT COALESCE(MAX(dokusya_rireki_id), 1) FROM t_dokusya_rireki));

COMMIT;

\echo 'Done. New V3 dokusya count:'
SELECT count(*) FROM t_dokusya WHERE ja_id = :jaid AND kumiaiin_code LIKE 'V3-%';
